"use client";
/**
 * v188 · «Ranking Juegos»: income generated by each game. A game's income is its share of the month's net commission
 * on changing euros ↔ cosmicoins, by its counted matches (lib/studioPayout.ts). Until that ledger exists the tab shows
 * sample data and says so («datos de ejemplo»). One series per chart (one hue, no legend): the month total over six
 * months, and each game's bar; tapping a game opens its own six-month line. Values are text, never colour alone, and
 * every chart has a table for screen readers.
 */
import { useMemo, useState } from "react";
import { GAMES } from "@/lib/games";
import { formatNumber, getLocale, t, useI18n } from "@/lib/i18n";
import { localeInfo } from "@/lib/i18n/locales";
import { gameName } from "@/lib/i18n/games";
import { SAMPLE_INCOME_MONTHS, sampleGameIncome } from "@/lib/demo/sampleGameIncome";
import st from "./GamesIncomeRanking.module.css";

const euros = (cents: number, decimals = 0) =>
  `${formatNumber(cents / 100, { minimumFractionDigits: decimals, maximumFractionDigits: decimals })} €`;

function lastMonths(now: Date) {
  return Array.from({ length: SAMPLE_INCOME_MONTHS }, (_, i) => new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - (SAMPLE_INCOME_MONTHS - 1 - i), 1)));
}

function LineChart({ values, labels, name }: { values: number[]; labels: string[]; name: string }) {
  const [pick, setPick] = useState(values.length - 1);
  const w = 300, h = 96, padTop = 22, padBottom = 6;
  const max = Math.max(...values, 1) * 1.08;
  const x = (i: number) => (values.length === 1 ? w / 2 : 12 + (i * (w - 24)) / (values.length - 1));
  const y = (v: number) => padTop + (1 - v / max) * (h - padTop - padBottom);
  const points = values.map((v, i) => `${x(i)},${y(v)}`).join(" ");
  const tipX = Math.min(w - 40, Math.max(40, x(pick)));
  return (
    <figure className={st.chart}>
      <svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label={t("ranking.gamesChartAria", { name })}>
        {[0.25, 0.5, 0.75].map((f) => <line key={f} x1="0" x2={w} y1={padTop + f * (h - padTop - padBottom)} y2={padTop + f * (h - padTop - padBottom)} className={st.grid} />)}
        <line x1="0" x2={w} y1={h - padBottom} y2={h - padBottom} className={st.base} />
        <polyline points={points} className={st.line} />
        {values.map((v, i) => <circle key={i} cx={x(i)} cy={y(v)} r={i === pick ? 4.5 : 3} className={i === pick ? st.dotOn : st.dot} />)}
        <text x={tipX} y={Math.max(12, y(values[pick]) - 9)} textAnchor="middle" className={st.tip}>{euros(values[pick])}</text>
        {values.map((_, i) => (
          <rect key={i} x={x(i) - (w - 24) / (2 * Math.max(1, values.length - 1))} y="0" width={(w - 24) / Math.max(1, values.length - 1)} height={h}
            className={st.hit} onPointerEnter={() => setPick(i)} onClick={() => setPick(i)} />
        ))}
      </svg>
      <div className={st.axis} aria-hidden="true">{labels.map((l, i) => <span key={i} data-on={i === pick || undefined}>{l}</span>)}</div>
      <table className="visuallyHidden">
        <caption>{t("ranking.gamesChartAria", { name })}</caption>
        <tbody>{labels.map((l, i) => <tr key={i}><th scope="row">{l}</th><td>{euros(values[i], 2)}</td></tr>)}</tbody>
      </table>
    </figure>
  );
}

export default function GamesIncomeRanking() {
  useI18n();
  const locale = getLocale();
  const months = useMemo(() => lastMonths(new Date()), []);
  const monthKey = months[months.length - 1].toISOString().slice(0, 7);
  const labels = useMemo(() => {
    const f = new Intl.DateTimeFormat(localeInfo(locale).intl, { month: "short", timeZone: "UTC" });
    return months.map((m) => f.format(m).replace(".", ""));
  }, [months, locale]);
  const income = useMemo(() => sampleGameIncome(GAMES.map((g) => g.id), monthKey), [monthKey]);
  const rows = useMemo(
    () => GAMES.map((g) => ({ game: g, series: income[g.id], now: income[g.id][SAMPLE_INCOME_MONTHS - 1] })).sort((a, b) => b.now - a.now),
    [income],
  );
  const totals = months.map((_, i) => rows.reduce((sum, r) => sum + r.series[i], 0));
  const top = rows[0]?.now ?? 1;
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className={st.wrap}>
      <p className={st.sample}>{t("ranking.exampleNotice")}</p>
      <section className={st.card} aria-labelledby="gi-total">
        <div className={st.cardHead}>
          <span id="gi-total">{t("ranking.gamesMonthTotal")}</span>
          <strong dir="ltr">{euros(totals[totals.length - 1])}</strong>
        </div>
        <small className={st.sub}>{t("ranking.gamesLast6")}</small>
        <LineChart values={totals} labels={labels} name={t("ranking.gamesAll")} />
      </section>
      <section aria-labelledby="gi-list">
        <h2 id="gi-list" className={st.listTitle}>{t("ranking.gamesByGame")}</h2>
        <ol className={st.list}>
          {rows.map((r, i) => {
            const isOpen = open === r.game.id;
            return (
              <li key={r.game.id} className={st.row} data-open={isOpen || undefined}>
                <button type="button" className={st.rowButton} aria-expanded={isOpen} onClick={() => setOpen(isOpen ? null : r.game.id)}>
                  <span className={st.pos}>{i + 1}</span>
                  <img src={r.game.cover} alt="" width={36} height={36} loading="lazy" />
                  <span className={st.name}>{gameName(r.game)}</span>
                  <b className={st.value} dir="ltr">{euros(r.now)}</b>
                  <span className={st.bar} aria-hidden="true"><i style={{ width: `${Math.max(2, (r.now / top) * 100)}%` }} /></span>
                </button>
                {isOpen && (
                  <div className={st.detail}>
                    <small className={st.sub}>{t("ranking.gamesEvolution", { game: gameName(r.game) })}</small>
                    <LineChart values={r.series} labels={labels} name={gameName(r.game)} />
                  </div>
                )}
              </li>
            );
          })}
        </ol>
      </section>
      <p className="rankingNote">{t("ranking.gamesNote")}</p>
    </div>
  );
}
